#include "stdlib/blas/base/shared.h"
#include "stdlib/blas/base/zrotg.h"
#include "stdlib/complex/float64/ctor.h"
#include "stdlib/complex/float64/real.h"
#include "stdlib/complex/float64/imag.h"
#include "stdlib/complex/float64/conj.h"
#include "stdlib/complex/float64/base/mul.h"
#include "stdlib/complex/float64/base/div.h"
#include "stdlib/math/base/special/abs.h"
#include "stdlib/math/base/special/sqrt.h"
#include <float.h>
#include <math.h>

/**
* Computes the squared absolute value of a complex number.
*
* @param z    complex number
* @return     squared absolute value
*/
static double cabs2( const stdlib_complex128_t z ) {
	double re = stdlib_complex128_real( z );
	double im = stdlib_complex128_imag( z );
	return ( re * re ) + ( im * im );
}

/**
* Constructs a Givens plane rotation using alternative indexing semantics.
*
* @param a        first rotational elimination parameter
* @param b        second rotational elimination parameter
* @param Out      output array
* @param strideOut  output stride length
* @param offsetOut  starting index for `Out`
*/
void API_SUFFIX( c_zrotg_assign )( const stdlib_complex128_t a, const stdlib_complex128_t b, double *Out, const CBLAS_INT strideOut, const CBLAS_INT offsetOut ) {
	double a_re, a_im, b_re, b_im;
	double za2, zb2, c2, c, d, scale;
	stdlib_complex128_t r, s, temp, scalar, conj_b;
	double safmin, safmax, rtmin, rtmax;
	const double EPS = DBL_EPSILON;

	// Extract real and imaginary parts
	a_re = stdlib_complex128_real( a );
	a_im = stdlib_complex128_imag( a );
	b_re = stdlib_complex128_real( b );
	b_im = stdlib_complex128_imag( b );

	// Compute safe scaling constants
	safmin = DBL_MIN / DBL_EPSILON;
	safmax = 1.0 / safmin;
	rtmin = sqrt( safmin );

	// Initialize s and r
	s = stdlib_complex128( 0.0, 0.0 );
	r = stdlib_complex128( 0.0, 0.0 );

	// Case 1: b is zero
	if ( b_re == 0.0 && b_im == 0.0 ) {
		c = 1.0;
		r = a;
	}
	// Case 2: a is zero
	else if ( a_re == 0.0 && a_im == 0.0 ) {
		c = 0.0;
		if ( b_re == 0.0 ) {
			d = stdlib_base_abs( b_im );
			r = stdlib_complex128( d, 0.0 );
			conj_b = stdlib_complex128_conj( b );
			s = stdlib_base_complex128_div( conj_b, r );
		} else if ( b_im == 0.0 ) {
			d = stdlib_base_abs( b_re );
			r = stdlib_complex128( d, 0.0 );
			conj_b = stdlib_complex128_conj( b );
			s = stdlib_base_complex128_div( conj_b, r );
		} else {
			zb2 = cabs2( b );
			d = stdlib_base_sqrt( zb2 );
			r = stdlib_complex128( d, 0.0 );
			conj_b = stdlib_complex128_conj( b );
			s = stdlib_base_complex128_div( conj_b, r );
		}
	}
	// Case 3: Both a and b are non-zero
	else {
		za2 = cabs2( a );
		zb2 = cabs2( b );
		c2 = za2 + zb2;

		if ( za2 >= c2 * EPS ) {
			c = stdlib_base_sqrt( za2 / c2 );
			r = stdlib_complex128( a_re / c, a_im / c );

			// Compute s = conj(b) * a / sqrt(za2 * c2) in a numerically stable way
			rtmax = sqrt( safmax / 2.0 );
			if ( za2 > rtmin && c2 < rtmax * rtmax ) {
				// safmin <= sqrt( za2*c2 ) <= safmax
				scale = 1.0 / stdlib_base_sqrt( c2 );
				temp = stdlib_complex128( a_re / stdlib_base_sqrt( za2 ), a_im / stdlib_base_sqrt( za2 ) );
				temp = stdlib_complex128( stdlib_complex128_real( temp ) * scale, stdlib_complex128_imag( temp ) * scale );
				conj_b = stdlib_complex128_conj( b );
				s = stdlib_base_complex128_mul( conj_b, temp );
			} else {
				scale = 1.0 / stdlib_base_sqrt( c2 );
				temp = stdlib_complex128( a_re / stdlib_base_sqrt( za2 ), a_im / stdlib_base_sqrt( za2 ) );
				temp = stdlib_complex128( stdlib_complex128_real( temp ) * scale, stdlib_complex128_imag( temp ) * scale );
				conj_b = stdlib_complex128_conj( b );
				s = stdlib_base_complex128_mul( conj_b, temp );
			}
		} else {
			// za2 / c2 <= EPS, so za2 is very small compared to zb2
			d = stdlib_base_sqrt( za2 * c2 );
			c = za2 / d;

			// Ensure c is not too small
			while ( c < EPS && c != 0.0 ) {
				d *= 2.0;
				c = za2 / d;
			}
			if ( c == 0.0 ) {
				c = 1.0;
			}

			r = stdlib_complex128( a_re / c, a_im / c );
			scalar = stdlib_complex128( 1.0 / d, 0.0 );
			conj_b = stdlib_complex128_conj( b );
			s = stdlib_base_complex128_mul( conj_b, stdlib_base_complex128_mul( a, scalar ) );
		}
	}

	// Store results in output array
	Out[ offsetOut ] = stdlib_complex128_real( r );
	Out[ offsetOut + strideOut ] = stdlib_complex128_imag( r );
	Out[ offsetOut + ( 2 * strideOut ) ] = c;
	Out[ offsetOut + ( 3 * strideOut ) ] = stdlib_complex128_real( s );
	Out[ offsetOut + ( 4 * strideOut ) ] = stdlib_complex128_imag( s );
	return;
}
